use std::{fs,path::Path};
use sha2::{Digest,Sha256};
pub const PRESETS:[(u32,u32);3]=[(500,50),(750,75),(1000,100)];
// Only recruitment, the population display and player defaults. No menu patches.
const SITES:[(usize,u8,u8,bool);9]=[(0xcf2a1,0x91,0xba,false),(0xcf2fa,0x91,0xba,false),(0xcf334,0x81,0xb8,false),(0xcf3a0,0xb1,0xbe,false),(0xd022e,0x86,0xb8,false),(0xcf244,0x81,0xb8,true),(0xcf279,0x91,0xba,true),(0xcf2d9,0x91,0xba,true),(0xd0267,0x86,0xb8,true)];
const HASHES:[&str;4]=["0e57f228dfce311fbd8a7d204f0e5cb323c09c784136ead23f632c23ccb7ebae","c5e1bccd0daa27a3581c1ba0dd2a1f51afd62798c8f8b390fcbbc8be3e1837a2","c20b4174ae0ed00ae778d036e6e9345bf034b4029f235cc3cc1f2134e3f87ae9","6f1bb5c3b3ad41fb28c18b54241139c1954ceefb17aae538b2089e4e56b48391"];
fn checksum(b:&mut[u8])->Result<(),String>{if b.len()<64{return Err("Ejecutable incompleto.".into())}let pe=u32::from_le_bytes(b[60..64].try_into().unwrap())as usize;let at=pe+88;if at+4>b.len(){return Err("Cabecera inválida.".into())}b[at..at+4].fill(0);let mut sum=0u64;for c in b.chunks(2){sum+=u16::from_le_bytes([c[0],*c.get(1).unwrap_or(&0)])as u64;sum=(sum&0xffff)+(sum>>16);}sum=(sum&0xffff)+(sum>>16);let n=(sum as u32&0xffff).wrapping_add(b.len()as u32);b[at..at+4].copy_from_slice(&n.to_le_bytes());Ok(())}
fn original(modrm:u8,groups:bool)->[u8;6]{[0x8b,modrm,if groups{0xa8}else{0xa4},3,0,0]}
const VILLAGES:[(usize,[u8;2]);2]=[(0xff0ce,[0x2b,0xc1]),(0xfdda7,[0x03,0xc2])];
pub fn villages(bytes:&[u8])->Result<bool,String>{let mut state=None;for(p,original)in VILLAGES{let b=bytes.get(p..p+2).ok_or("Ejecutable incompleto")?;let on=if b==original{false}else if b==[0x90,0x90]{true}else{return Err("Código de población no reconocido. No se modifica.".into())};if state.is_some_and(|v|v!=on){return Err("El ajuste de aldeas está incompleto.".into())}state=Some(on);}Ok(state.unwrap_or(false))}
fn base(bytes:&[u8])->Result<(Vec<u8>,(u32,u32)),String>{if bytes.len()!=3551232{return Err("Esta versión del ejecutable no está admitida. No se modifica.".into())}let mut b=bytes.to_vec();villages(bytes)?;for(p,original)in VILLAGES{b[p..p+2].copy_from_slice(&original);}let mut state=None;
 for(pos,modrm,op,groups)in SITES{let raw=&b[pos..pos+6];let value=if raw==original(modrm,groups){None}else if raw[0]==op&&raw[5]==0x90{Some(u32::from_le_bytes(raw[1..5].try_into().unwrap()))}else{return Err(format!("Código inesperado en {pos:x}. No se modifica."))};let expected=state.get_or_insert(value.map(|n|if groups{n*10}else{n}));if *expected!=value.map(|n|if groups{n*10}else{n}){return Err("Los límites existentes no son coherentes.".into())}b[pos..pos+6].copy_from_slice(&original(modrm,groups));}
 let current=state.flatten().unwrap_or(500);if !PRESETS.iter().any(|(t,_)|*t==current){return Err("El límite actual no está admitido.".into())}
 for(pos,field,value)in [(0xcb1b3,0xa4,current),(0xcb1bd,0xa8,current/10)]{if b[pos..pos+6]!=[0xc7,0x86,field,3,0,0]||u32::from_le_bytes(b[pos+6..pos+10].try_into().unwrap())!=value{return Err("Los valores iniciales no coinciden.".into())}b[pos+6..pos+10].copy_from_slice(&(if field==0xa4{500u32}else{50u32}).to_le_bytes());}
 let pe=u32::from_le_bytes(b[60..64].try_into().unwrap())as usize;b[pe+88..pe+92].fill(0);let hash=format!("{:x}",Sha256::digest(&b));if !HASHES.contains(&hash.as_str()){return Err("El ejecutable contiene otros cambios. Se conserva sin modificar.".into())}Ok((b,(current,current/10)))}
pub fn inspect(bytes:&[u8])->Result<(u32,u32),String>{Ok(base(bytes)?.1)}
pub fn patch(bytes:&[u8],troops:u32)->Result<Vec<u8>,String>{let groups=PRESETS.iter().find(|(t,_)|*t==troops).ok_or("Selecciona 500/50, 750/75 o 1000/100.")?.1;let(mut b,_)=base(bytes)?;if troops!=500{for(pos,_,op,group)in SITES{b[pos]=op;b[pos+1..pos+5].copy_from_slice(&(if group{groups}else{troops}).to_le_bytes());b[pos+5]=0x90;}b[0xcb1b9..0xcb1bd].copy_from_slice(&troops.to_le_bytes());b[0xcb1c3..0xcb1c7].copy_from_slice(&groups.to_le_bytes());}if villages(bytes)?{for(p,_)in VILLAGES{b[p..p+2].fill(0x90);}}if troops!=500||villages(bytes)?{checksum(&mut b)?;}Ok(b)}
pub fn running()->bool{#[cfg(windows)]unsafe{#[link(name="user32")]extern "system"{fn FindWindowW(a:*const u16,b:*const u16)->isize;}let n:Vec<_>="Praetorians".encode_utf16().chain(Some(0)).collect();return FindWindowW(std::ptr::null(),n.as_ptr())!=0}#[cfg(not(windows))]false}
pub fn patch_options(bytes:&[u8],troops:u32,unlimited:bool)->Result<Vec<u8>,String>{let mut b=patch(bytes,troops)?;for(p,original)in VILLAGES{if unlimited{b[p..p+2].fill(0x90);}else{b[p..p+2].copy_from_slice(&original);}}if troops!=500||unlimited{checksum(&mut b)?;}else{let pe=u32::from_le_bytes(b[60..64].try_into().unwrap())as usize;b[pe+88..pe+92].fill(0);}Ok(b)}
pub fn apply(root:&Path,troops:u32)->Result<String,String>{let old=fs::read(root.join("Praetorians.exe")).map_err(|e|e.to_string())?;apply_options(root,troops,villages(&old)?)}
pub fn apply_options(root:&Path,troops:u32,unlimited:bool)->Result<String,String>{if running(){return Err("Cierra Praetorians antes de aplicar.".into())}let exe=root.join("Praetorians.exe");let old=fs::read(&exe).map_err(|e|format!("No se puede leer Praetorians.exe: {e}"))?;let new=patch_options(&old,troops,unlimited)?;if new==old{return Ok("Esta opción ya está aplicada.".into())}let stamp=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();let backup=root.join("OpcionesUnidades.Backups").join(stamp.to_string());fs::create_dir_all(&backup).map_err(|e|e.to_string())?;fs::write(backup.join("Praetorians.exe"),&old).map_err(|e|e.to_string())?;let next=root.join(format!("OpcionesUnidades-{stamp}.tmp"));let previous=root.join(format!("OpcionesUnidades-{stamp}.prev"));fs::write(&next,&new).map_err(|e|e.to_string())?;if fs::read(&exe).map_err(|e|e.to_string())?!=old{return Err("El juego cambió durante la operación. No se sobrescribe.".into())}fs::rename(&exe,&previous).map_err(|e|e.to_string())?;if let Err(e)=fs::rename(&next,&exe){let _=fs::rename(&previous,&exe);return Err(format!("No se pudo aplicar: {e}"))}let _=fs::remove_file(previous);Ok(format!("Aplicado: {troops} tropas / {} grupos. Población inagotable: {}. Copia de recuperación guardada.",troops/10,if unlimited{"activada"}else{"desactivada"}))}
#[cfg(test)]mod tests{use super::*;
 #[test]fn all_presets_roundtrip_and_no_unrelated_changes(){let p=Path::new("C:/Games/Praetorians/Praetorians.exe");let original=patch(&fs::read(p).unwrap(),500).unwrap();for(t,g)in PRESETS{let b=patch(&original,t).unwrap();assert_eq!(inspect(&b).unwrap(),(t,g));assert_eq!(patch(&b,500).unwrap(),original);assert_eq!(patch(&b,t).unwrap(),b);let pe=u32::from_le_bytes(original[60..64].try_into().unwrap())as usize;for(i,(a,b))in original.iter().zip(&b).enumerate(){if a!=b{assert!(SITES.iter().any(|(p,_,_,_)|(*p..*p+6).contains(&i))||(0xcb1b9..0xcb1bd).contains(&i)||(0xcb1c3..0xcb1c7).contains(&i)||(pe+88..pe+92).contains(&i),"Unexpected edit {i:x}");}}}}
 #[test]fn unknown_exe_and_partial_patch_rejected(){let mut b=fs::read("C:/Games/Praetorians/Praetorians.exe").unwrap();b[0x15000]^=1;assert!(patch(&b,750).is_err());assert!(patch(&b,600).is_err());}
 #[test]fn all_native_display_variants_supported(){for n in ["4x3","16x9","16x10","XxX"]{let b=fs::read(format!("C:/Games/Praetorians/Praetorians_{n}_exe.bak")).unwrap();let x=patch(&b,1000).unwrap();assert_eq!(inspect(&x).unwrap(),(1000,100));assert_eq!(patch(&x,500).unwrap(),b);}}
}

#[cfg(test)]mod village_tests{use super::*;
 #[test]fn villages_roundtrip_all_variants_and_limits(){for name in ["4x3","16x9","16x10","XxX"]{let b=fs::read(format!("C:/Games/Praetorians/Praetorians_{name}_exe.bak")).unwrap();for(t,g)in PRESETS{let on=patch_options(&b,t,true).unwrap();assert_eq!(inspect(&on).unwrap(),(t,g));assert!(villages(&on).unwrap());let off=patch_options(&on,t,false).unwrap();assert!(!villages(&off).unwrap());assert!(off==patch_options(&b,t,false).unwrap());assert!(patch_options(&on,500,false).unwrap()==b);for(i,(a,c))in on.iter().zip(patch(&b,t).unwrap()).enumerate(){if *a!=c{let pe=u32::from_le_bytes(b[60..64].try_into().unwrap())as usize;assert!(VILLAGES.iter().any(|(p,_)|(*p..*p+2).contains(&i))||(pe+88..pe+92).contains(&i));}}}}}
 #[test]fn partial_village_patch_rejected(){let mut b=fs::read("C:/Games/Praetorians/Praetorians_4x3_exe.bak").unwrap();b[0xff0ce..0xff0d0].fill(0x90);assert!(inspect(&b).is_err());}
}
